@pytest.mark.parametrize(
    ("mutation", "match"),
    [
        ("missing", "H-share famous-stock quote row 0 is missing field"),
        ("unexpected", "H-share famous-stock quote row 0 contains unsupported field"),
        ("field_order", "must preserve the official field order"),
        ("invalid_rank", "field '序号' must be a positive integer"),
        ("duplicate_rank", "序号 values must be strictly ascending"),
        ("invalid_code", "has an invalid 代码"),
        ("duplicate_code", "duplicate 代码"),
        ("invalid_name", "field '名称' must be a non-empty string"),
        ("invalid_numeric", "field '最新价' must be numeric or null"),
    ],
)
def test_hk_famous_quote_response_validates_exact_fields_identity_order_and_values(
    mutation: str,
    match: str,
):
    class InvalidRows(FakeAKShare):
        def stock_hk_famous_spot_em(self):
            rows = [dict(row) for row in _fixture("h_famous_quote.json")]
            if mutation == "missing":
                rows[0].pop("成交额")
            elif mutation == "unexpected":
                rows[0]["unexpected"] = "not documented"
            elif mutation == "field_order":
                first = rows[0]
                rows[0] = {
                    "代码": first["代码"],
                    **{key: value for key, value in first.items() if key != "代码"},
                }
            elif mutation == "invalid_rank":
                rows[0]["序号"] = 0
            elif mutation == "duplicate_rank":
                rows[1]["序号"] = rows[0]["序号"]
            elif mutation == "invalid_code":
                rows[0]["代码"] = "0700"
            elif mutation == "duplicate_code":
                rows[1]["代码"] = rows[0]["代码"]
            elif mutation == "invalid_name":
                rows[0]["名称"] = ""
            else:
                rows[0]["最新价"] = "521.5"
            return self._return("stock_hk_famous_spot_em", rows)

    with pytest.raises(ProviderResponseError, match=match):
        _provider(InvalidRows()).fetch(
            _request(
                DataCategory.MARKET_QUOTE,
                "HK00700",
                {"view": "hk_famous"},
            )
        )


