    assert metadata["integer_fields"] == []
    assert metadata["text_fields"] == []
    assert metadata["date_fields"] == ["日期"]
    assert metadata["required_date_fields"] == ["日期"]
    assert metadata["required_numeric_fields"] == numeric_fields
