@pytest.mark.parametrize(
    "mutation",
    [
        "empty",
        "missing_field",
        "extra_field",
        "reordered_fields",
        "invalid_date",
        "duplicate_date",
        "descending_dates",
        "invalid_numeric",
        "boolean_numeric",
        "negative_index",
        "null_numeric",
    ],
)
def test_market_activity_index_pb_response_validates_schema_boundaries(
    mutation: str,
):
    payload = [dict(row) for row in _fixture("index_pb.json")]
    if mutation == "empty":
        payload = []
    elif mutation == "missing_field":
        payload[0].pop("指数")
    elif mutation == "extra_field":
        payload[0]["unexpected"] = "not documented"
    elif mutation == "reordered_fields":
        payload[0] = dict(reversed(list(payload[0].items())))
    elif mutation == "invalid_date":
        payload[0]["日期"] = "2005-1-5"
    elif mutation == "duplicate_date":
        payload[1]["日期"] = payload[0]["日期"]
    elif mutation == "descending_dates":
        payload.reverse()
    elif mutation == "invalid_numeric":
        payload[0]["市净率"] = "not-a-number"
    elif mutation == "boolean_numeric":
        payload[0]["市净率"] = True
    elif mutation == "negative_index":
        payload[0]["指数"] = -1
    else:
        payload[0]["市净率"] = None

    class InvalidIndexPb(FakeAKShare):
        def stock_index_pb_lg(self, *, symbol: str):
            return self._return("stock_index_pb_lg", payload, symbol=symbol)

    with pytest.raises(ProviderResponseError):
        _provider(InvalidIndexPb()).fetch(
            _request(
                DataCategory.MARKET_ACTIVITY,
                "SH600000",
                {"view": "index_pb", "symbol": "上证50"},
            )
        )


