@pytest.mark.parametrize(
    "mutation",
    [
        "empty",
        "short",
        "missing_field",
        "extra_field",
        "reordered_fields",
        "target_code",
        "target_rank",
        "summary_code",
        "summary_name",
        "summary_rank",
        "peer_code",
        "duplicate_peer",
        "peer_rank",
        "descending_peer_ranks",
        "invalid_numeric",
        "boolean_numeric",
    ],
)
def test_market_activity_valuation_comparison_response_validates_schema_boundaries(
    mutation: str,
):
    payload = [dict(row) for row in _fixture("a_valuation_comparison.json")]
    if mutation == "empty":
        payload = []
    elif mutation == "short":
        payload = payload[:2]
    elif mutation == "missing_field":
        payload[0].pop("PEG")
    elif mutation == "extra_field":
        payload[0]["unexpected"] = "not documented"
    elif mutation == "reordered_fields":
        payload[0] = dict(reversed(list(payload[0].items())))
    elif mutation == "target_code":
        payload[0]["代码"] = "000001"
    elif mutation == "target_rank":
        payload[0]["排名"] = "nan"
    elif mutation == "summary_code":
        payload[1]["代码"] = "行业总和"
    elif mutation == "summary_name":
        payload[1]["简称"] = "行业平均"
    elif mutation == "summary_rank":
        payload[1]["排名"] = "1.0"
    elif mutation == "peer_code":
        payload[3]["代码"] = "ABC"
    elif mutation == "duplicate_peer":
        payload[4]["代码"] = payload[3]["代码"]
    elif mutation == "peer_rank":
        payload[3]["排名"] = "nan"
    elif mutation == "descending_peer_ranks":
        payload[4]["排名"] = "1.0"
    elif mutation == "invalid_numeric":
        payload[0]["PEG"] = "not-a-number"
    else:
        payload[0]["PEG"] = True

    class InvalidValuationComparison(FakeAKShare):
        def stock_zh_valuation_comparison_em(self, *, symbol: str):
            return self._return(
                "stock_zh_valuation_comparison_em",
                payload,
                symbol=symbol,
            )

    with pytest.raises(ProviderResponseError):
        _provider(InvalidValuationComparison()).fetch(
            _request(
                DataCategory.MARKET_ACTIVITY,
                "SZ000895",
                {"view": "valuation_comparison"},
            )
        )


def test_market_activity_valuation_comparison_allows_nullable_signed_multiples():
    payload = [dict(row) for row in _fixture("a_valuation_comparison.json")]
    payload[0]["PEG"] = None
    payload[0]["市现率2-24A"] = -123.45

    class NullableValuationComparison(FakeAKShare):
        def stock_zh_valuation_comparison_em(self, *, symbol: str):
            return self._return(
                "stock_zh_valuation_comparison_em",
                payload,
                symbol=symbol,
            )

    record = _provider(NullableValuationComparison()).fetch(
        _request(
            DataCategory.MARKET_ACTIVITY,
            "SZ000895",
            {"view": "valuation_comparison"},
        )
    )

    assert record.raw_payload[0]["PEG"] is None
    assert record.raw_payload[0]["市现率2-24A"] == -123.45
    assert record.response_metadata["nullable_fields"] == record.response_metadata[
        "value_fields"
    ]


def test_market_activity_valuation_comparison_is_retained_as_raw_evidence_without_facts():
    record = _provider().fetch(
        _request(
            DataCategory.MARKET_ACTIVITY,
            "SZ000895",
            {"view": "valuation_comparison"},
        )
    )
    normalized = normalize_akshare_records(
        [record],
        analysis_id="valuation-comparison-raw-only",
        as_of=date(2026, 9, 11),
        profile_id="strict-v1",
        company=_company("SZ000895"),
    )

    assert normalized.facts == []
    assert normalized.evidence_index
    assert normalized.flags == ["AKSHARE_VALUATION_COMPARISON_RAW_ONLY"]
    assert normalized.data_quality.critical_missing_fields == []
    assert normalized.data_quality.confidence.value == "LOW"
    assert "Eastmoney" in normalized.data_quality.notes
    assert "valuation-comparison" in normalized.data_quality.notes
    assert "canonical valuation" in normalized.data_quality.notes

    schema = json.loads(SCHEMA_PATH.read_text(encoding="utf-8"))
    assert list(
        Draft202012Validator(schema).iter_errors(normalized.model_dump(mode="json"))
    ) == []


